import type { SimulationModel, StepSign } from "@ise/science-engine";
import { TAU, normalizeRadians, shortestDelta, snapZero, wrapInto } from "@ise/units";
import { cosOf, sinOf, snappedStep } from "./unit-circle";

/**
 * y = A sin(ωx + φ) + d.
 *
 * A probe point moves along x. The same wave is generated by a point rotating
 * on a circle of radius |A| centred at height d, whose angle is ωx + φ — the
 * unit-circle construction, stretched, sped up and shifted.
 */

export type SinusoidParams = {
  /** A — may be negative (reflects the wave). */
  amplitude: number;
  /** ω — radians of phase per unit of x. */
  omega: number;
  /** φ — phase at x = 0, rad. */
  phi: number;
  /** d — vertical offset (midline). */
  offset: number;
  /** Probe speed along x, x-units per second. */
  probeSpeed: number;
  /** Discrete step for the probe, x-units. */
  stepSize: number;
};

/** Visible x-range [−2π, 2π); the probe wraps around it. */
export const X_MIN = -TAU;
export const X_MAX = TAU;
const WIDTH = X_MAX - X_MIN;

export interface SinusoidState {
  /** Probe position, unwrapped (continuous across passes of the x-range). */
  readonly x: number;
  readonly time: number;
}

export type SinusoidResults = {
  /** Probe position inside [xMin, xMax). */
  xProbe: number;
  y: number;
  /** ωx + φ at the probe, rad (unwrapped and wrapped into [0, 2π)). */
  phase: number;
  phaseNorm: number;
  /** Point on the generating circle, relative to its centre (0, d). */
  phasorX: number;
  phasorY: number;
  amplitude: number;
  amplitudeSigned: number;
  omega: number;
  phi: number;
  offset: number;
  /** Period T = 2π/|ω| (x-units). */
  period: number;
  /** Cycles per unit of x = |ω|/2π. */
  frequency: number;
  /** ω·T — always 2π; the pattern the discovery activity uncovers. */
  omegaTimesPeriod: number;
  max: number;
  min: number;
  /** Horizontal shift of the wave relative to sin x: −φ/ω. */
  phaseShift: number;
  /** First maximum at or after xMin. */
  peakX: number;
  /** How many full periods fit in the visible range. */
  cyclesShown: number;
  passes: number;
  time: number;
};

export interface WaveParams {
  amplitude: number;
  omega: number;
  phi: number;
  offset: number;
}

/** The single evaluation of the sinusoid used by the model and every renderer. */
export function sinusoidAt(x: number, p: WaveParams): number {
  return snapZero(p.offset + p.amplitude * sinOf(p.omega * x + p.phi));
}

export function periodOf(omega: number): number {
  return omega === 0 ? Number.POSITIVE_INFINITY : TAU / Math.abs(omega);
}

/** First x ≥ xMin at which the wave reaches its maximum d + |A|. */
export function firstPeak(p: WaveParams, xMin: number): number {
  if (p.omega === 0 || p.amplitude === 0) return Number.NaN;
  // Maximum where sin(ωx + φ) = ±1, depending on the sign of A.
  const target = p.amplitude > 0 ? Math.PI / 2 : (3 * Math.PI) / 2;
  const base = (target - p.phi) / p.omega;
  return wrapInto(base, xMin, periodOf(p.omega));
}

const OUTPUTS = [
  "xProbe",
  "y",
  "phase",
  "phaseNorm",
  "phasorX",
  "phasorY",
  "amplitude",
  "amplitudeSigned",
  "omega",
  "phi",
  "offset",
  "period",
  "frequency",
  "omegaTimesPeriod",
  "max",
  "min",
  "phaseShift",
  "peakX",
  "cyclesShown",
  "passes",
  "time",
] as const satisfies readonly (keyof SinusoidResults)[];

export const sinusoidModel: SimulationModel<SinusoidState, SinusoidParams, SinusoidResults> = {
  id: "sinusoid",
  defaultParams: {
    amplitude: 1,
    omega: 1,
    phi: 0,
    offset: 0,
    probeSpeed: Math.PI / 2,
    stepSize: Math.PI / 12,
  },
  outputs: OUTPUTS,
  stateVariables: ["x"],

  initialize() {
    return { x: 0, time: 0 };
  },

  advance(state, dt, params) {
    return { x: state.x + params.probeSpeed * dt, time: state.time + dt };
  },

  step(state, params, sign: StepSign) {
    return { ...state, x: snappedStep(state.x, params.stepSize, sign) };
  },

  derive(state, params) {
    const { amplitude: A, omega, phi, offset: d } = params;
    const xProbe = wrapInto(state.x, X_MIN, WIDTH);
    const phase = omega * xProbe + phi;
    const period = periodOf(omega);
    return {
      xProbe,
      y: sinusoidAt(xProbe, params),
      phase,
      phaseNorm: normalizeRadians(phase),
      phasorX: snapZero(A * cosOf(phase)),
      phasorY: snapZero(A * sinOf(phase)),
      amplitude: Math.abs(A),
      amplitudeSigned: A,
      omega,
      phi,
      offset: d,
      period,
      frequency: Math.abs(omega) / TAU,
      omegaTimesPeriod: Math.abs(omega) * period,
      max: d + Math.abs(A),
      min: d - Math.abs(A),
      phaseShift: omega === 0 ? Number.NaN : snapZero(-phi / omega),
      peakX: firstPeak(params, X_MIN),
      cyclesShown: WIDTH / period,
      passes: Math.floor((state.x - X_MIN) / WIDTH + 1e-12),
      time: state.time,
    };
  },

  getVariable(state, id) {
    return id === "x" ? wrapInto(state.x, X_MIN, WIDTH) : undefined;
  },

  /** Moves the probe to the nearest equivalent position, so drags wrap smoothly. */
  setVariable(state, id, value) {
    if (id !== "x") return state;
    const xProbe = wrapInto(state.x, X_MIN, WIDTH);
    return { ...state, x: state.x + shortestDelta(xProbe, value, WIDTH) };
  },

  // The trace records x − X_MIN (so the range starts at 0); graphs draw it with offset X_MIN.
  trace: {
    coordinate: (state) => state.x - X_MIN,
    period: WIDTH,
    channels: ["y"],
    sample: (c, params) => ({ y: sinusoidAt(c + X_MIN, params) }),
    // Changing the wave makes every recorded sample stale.
    resetOn: ["amplitude", "omega", "phi", "offset"],
  },
};
